-- ════════════════════════════════════════════════════════════════════════════
--  133 · Rastreio — motivos novos do cruzamento dos 600 pendentes da Jetpack com o painel FulFil (pedido do Lucas, 16/11/2026)
--
--  A Jetpack junta pedidos do mesmo cliente num envio só; quando a soma passa de 25 frascos, o envio fica em hold. São 10 envios (26 referências
--  nossas). E 8 referências foram canceladas na Jetpack, mas a API do JetStream ainda diz "processing" (2 como teste, 6 sem motivo visível).
--    situacao ganha: hold_frascos | cancelado
--  Aditiva e idempotente. Desfazer: DELETE FROM rastreio_situacao_fulfillment WHERE situacao IN ('hold_frascos', 'cancelado') e voltar o CHECK de 132.
-- ════════════════════════════════════════════════════════════════════════════
ALTER TABLE public.rastreio_situacao_fulfillment DROP CONSTRAINT IF EXISTS rastreio_situacao_fulfillment_situacao_check;
ALTER TABLE public.rastreio_situacao_fulfillment ADD CONSTRAINT rastreio_situacao_fulfillment_situacao_check
  CHECK (situacao IN ('nao_entrou', 'hold_endereco', 'hold_frascos', 'cancelado_teste', 'cancelado'));

